source("pre.R")
tw <- id_layout("twitter")
s1 <- id_parse(c("9","10","100"), "snowflake", layout=tw)
p("max/min/range snowflake", list(max(s1), min(s1), range(s1)))
p("rank", rank(s1)); p("order 2 keys", order(c(1,1,1), s1)); p("sort method quick", sort(s1, method="quick")); p("rev sort", sort(s1, decreasing=TRUE)); p("order decreasing", order(s1, decreasing=TRUE)); p("sort.int", sort.int(s1)); p("which.max", which.max(s1))
u <- "018f6b1c-2d3e-7a4b-8c5d-6e7f8091a2b3"
p("detect==explicit", identical(id_parse(u), id_parse(u, "uuid")))
for (g in list(uuid(2), uuid(2,4), ulid(2), typeid(2,"a"), typeid(2,""), upid(2,"a"), scru128(2), ksuid(2), xid(2), objectid(2), nanoid(2), sqids(1:2), scru64(2, 1, 4, rollback="reset"))) cat(attr(g,"format"), identical(id_parse(as.character(g), attr(g,"format")), g), identical(id_parse(g), g), all(id_valid(g, attr(g,"format"), level="strict")), "\n")
sn <- snowflake(2, tw, list(worker=1, datacenter=2), rollback="reset"); p("snowflake reparse identical", identical(id_parse(as.character(sn), "snowflake", layout=tw), sn))
p("snowflake parse zuid no layout arg", identical(id_parse(sn), sn)); p("snowflake parse zuid other layout", attr(id_parse(sn, layout=id_layout("discord")), "layout")$name)
l8 <- id_layout("scru64", node_bits=8); g <- scru64(1, 1, 8, rollback="reset"); pl <- id_parse(as.character(g), "scru64", layout=l8)
p("c scru64 gen + parsed-with-layout", c(g, pl)); p("==", g == pl)
p("scru64 parse with wrong node_bits", id_fields(id_parse(as.character(g), "scru64", layout=id_layout("scru64", node_bits=4)))[,c("node","sequence")])
p("nanoid explicit default alphabet identical", identical(attributes(id_parse("abc","nanoid", alphabet="57X6y3wQZNzYjJB2L_10pxbackgroundhimselfUTF-8DEMOGRAPHICSVqvt4KW9")), attributes(id_parse("abc","nanoid"))))
p("nanoid default alphabet is 64 distinct", {a <- strsplit(zuid:::nanoid_alphabet, "")[[1]]; c(length(a), anyDuplicated(a))})
p("nanoid permuted default alphabet", {x <- id_parse("abc","nanoid", alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-"); y <- id_parse("abc","nanoid"); t(c(x,y))})
p("elementwise vs vector parse", {v <- c(u, "x", NA, toupper(u)); identical(as.character(id_parse(v,"uuid")), vapply(v, function(e) as.character(id_parse(e,"uuid")), "", USE.NAMES=FALSE))})
p("fields elementwise", {x <- uuid(3,1); identical(id_fields(x), do.call(rbind, lapply(seq_along(x), function(i) id_fields(x[i]))))})
p("typeid sort same prefix", {x <- typeid(3, "a", time=c(3e12,1e12,2e12)); order(x)})
p("upid sort", {x <- upid(3, "a", time=c(3e12,1e12,2e12)); order(x)})
p("uuid sort upper input", order(id_parse(c("B0000000-0000-4000-8000-000000000000","a0000000-0000-4000-8000-000000000000"),"uuid")))
p("unique canonical", length(unique(id_parse(c(u, toupper(u)), "uuid"))))
p("xid process -1/NA/1.5/chr", list(t(xid(1,process=-1)), t(xid(1,process=NA)), t(xid(1,process=1.5)), t(xid(1,process="1")), id_fields(xid(1,process=65536+7))$process))
p("xid machine", list(id_fields(xid(1, machine=as.raw(1:3)))$node, t(xid(1, machine=raw(2))), t(xid(1, machine=1:3)), t(xid(1, machine=as.raw(1:3), random=raw(6)))))
p("xid random n-dependence", t(xid(3, random=raw(18))))
p("factor col in df", {d <- data.frame(id = factor(u)); t(id_parse(d$id, "uuid"))})
p("typeid text NA suffix", id_convert(id_parse(c(u, NA), "uuid"), "typeid", "a"))
